@module gridPane  src=gridPane.lua  loc=1194  mode=chunk  self=gridPane
@deps cm, cmgr, chrome, gui, tv, inputAllowed, chordEntry

# Invariants & contracts
  @invariant  grid render + input only; tracker state lives in tv/ec, never cached here  @ 4
  @invariant  col.x == nil is the visibility predicate; per-column draws must gate on it  @ 5
  @invariant  cell coords 0-indexed; header rows at -HEADER, row-num gutter at -GUTTER  @ 6
  @invariant  page-persistent state: cellW/H, dragging, laneConsumed, paintLast  @ 7
  @contract  host supplies inputAllowed() -- folds modal/picker/item-active/palette/strip gates  @ 8
  @contract  host chordEntry=false gates the chord gesture off (the pattern editor passes false)  @ 9
  @contract  bails if laneConsumed; lane strip wins gestures over the tracker grid  @ 991
  @contract  right-click on channel-label row toggles mute  @ 992
  @contract  click on label rows selects channel/column  @ 993
  @contract  body click moves cursor and arms drag  @ 994
  @contract  no-op unless inputAllowed(); host folds modal/picker/item-active/palette/strip  @ 1134
  @contract  every fresh press enters; only lastEditKey autorepeats  @ 1135
  @contract  scans editKeys per frame; reads ec/grid fresh (editEvent may rebuild)  @ 1136
  @contract  a note key typed while armed exits region mode then enters (execute-through)  @ 1137
  @contract  Shift+notechar strikes chords (+Alt spreads channels); Shift+digit value place-walk  @ 1138
  @contract  Backspace deletes last chord note; Shift+=/- nudges vel; shift release commits  @ 1139

# Imports
  @require util = 'util'  @ 10
  @require groups = 'groups'  @ 11
  @require ImGui = 'imgui'  @ 17
  @require painter = 'painter'  @ 18

# Constructed sub-instances
  @construct curveEditor = util.instantiate('curveEditor')  @ 59

# Private state
  @state GUTTER = 5  @ 25   -- in grid chars: 3-char row num + spacer + region slot
  @state HEADER = 3  @ 26   -- header rows, fixed; vertical param names truncate to fit, never grow it
  @state RESERVE_ROWS = 0.3  @ 27   -- bottom breathing left clear below the last row (status band / modal edge)
  @state ANCHOR_HALO = 6  @ 28   -- px; matches curveEditor HIT_PX so the hit-rect covers anchors on the rect edge
  @state cellW = nil  @ 30   -- px per cell; set on first computeLayout
